insert into public.permission_catalog(key,domain,name,description,module,action,scopes,dependencies) values('backoffice.functions.cockpit_overview_query','tenant','Operationeel en managementoverzicht lezen','Eén geautoriseerd overzicht met unieke bezoeken en dezelfde native modulecijfers.','overview','read',array['tenant'],array['backoffice.access','backoffice.overview.read']) on conflict(key) do nothing;
insert into private.management_role_permissions(tenant_id,role_id,capability) select r.tenant_id,r.id,'backoffice.functions.cockpit_overview_query' from private.management_roles r where r.code='owner' or exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability='backoffice.overview.read') on conflict do nothing;
insert into public.permission_catalog(key,domain,name,description,module,action,scopes,dependencies) values('backoffice.functions.cockpit_work_order_financial_sources','tenant','Financiële werkbonbronnen lezen','De canonieke bronregels in een bestaand geautoriseerd werkbondossier.','finance','read',array['tenant'],array['backoffice.work_orders.read','backoffice.functions.work_order_dossier','backoffice.functions.cockpit_finance_query']) on conflict(key) do nothing;
insert into private.management_role_permissions(tenant_id,role_id,capability) select r.tenant_id,r.id,'backoffice.functions.cockpit_work_order_financial_sources' from private.management_roles r where r.code='owner' or(exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability='backoffice.functions.work_order_dossier') and exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability='backoffice.functions.cockpit_finance_query')) on conflict do nothing;
